@startuml

class Person {
  + personID : string
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : string
}

class Article {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends Article {
  + citationCount : int
}

class TechnicalReport extends Article {}

class AuthorPosition {
  + position : string
}

class Reviewer {
  + reviewDetails : string
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "*" Article : authors
Article "1" -- "*" AuthorPosition : has
Person "1" -- "*" AuthorPosition : in_position

Person "1" -- "0..*" Reviewer : reviews
PeerReviewedPaper "1" -- "0..*" Reviewer : is_reviewed_by

Institution "1" -- "*" Person : employs
Institution "1" -- "*" TechnicalReport : publishes
Journal "0..*" -- "1" Publisher : published_by
Journal "*" -- "*" Institution : subscribed_by
PeerReviewedPaper "*" -- "0..1" Journal : published_in

@enduml

